solution.solution.cpp:
bool isVowel(char c)
{
    switch (c)
    {
    case 'a': case 'e': case 'i': case 'o': case 'u':
    case 'A': case 'E': case 'I': case 'O': case 'U':
        return true;
    default:
        return false;
    }
}

unitTests:
TEST("lower-case vowels") { CHECK(isVowel('a')); CHECK(isVowel('e')); CHECK(isVowel('i')); CHECK(isVowel('o')); CHECK(isVowel('u')); }
TEST("upper-case vowels") { CHECK(isVowel('A')); CHECK(isVowel('U')); }
TEST("consonants and other characters") { CHECK(!isVowel('b')); CHECK(!isVowel('Z')); CHECK(!isVowel('7')); CHECK(!isVowel(' ')); }

